  "cue": "guiding_arm",
  "description": "Extends an arm to the side and sweeps it forward to guide or indicate a direction.",
  "movements": [
    {
      "type": "pose",
      "duration": 0.5,
      "parameters": {
        "pose": {
          "torso_height": "mid",
          "arm_position": "out",
          "gripper_orientation": "horizontal",
          "head": "center",
          "elbow_bended": false,
          "z": 60
        }
      }
    },
    {
      "type": "movement",
      "duration": 0.6,
      "parameters": {
        "movement": {
          "joints": [
            {
              "joint": "head",
              "axis": "pan",
              "degrees": [
                0,
                -30
              ]
            }
          ],
          "repetition": 1,
          "speed": 1.8
        }
      }
    },
    {
      "type": "path",
      "duration": 1.4,
      "parameters": {
        "path": {
          "mode": "ee",
          "shape": "arc",
          "plane": "xy",
          "radius": 0.35,
          "sweep": 70,
          "direction": "ccw",
          "speed": 1.2,
          "hold_time": 0.5
        }
      }
    }
  ]
}
